<template><AppShell><PageHeader title="Operational Overview" subtitle="Real-time logistics throughput, inventory health, and dispatch control."><a class="btn-secondary" href="/reports/export">Export Report</a></PageHeader><section class="rounded-lg bg-navy p-6 text-white shadow-lg"><p class="text-sm font-bold uppercase tracking-widest text-gold">System Status: Active</p><h2 class="mt-3 font-display text-4xl font-extrabold">Vic Enterprise Logistics Management System</h2><p class="mt-2 max-w-2xl text-blue-100">Mission-control dashboard for Century Peak cement operations.</p></section><section class="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><KpiCard label="MTD Volume" :value="kpis.mtd_volume"/><KpiCard label="Last Month Volume" :value="kpis.last_month_volume"/><KpiCard label="YTD Volume" :value="kpis.ytd_volume"/><KpiCard label="Annual Target Progress" :value="kpis.annual_target_progress + '%'"/></section><section class="mt-6 grid gap-6 xl:grid-cols-3"><div class="xl:col-span-2"><div class="mb-3 flex items-center justify-between"><h2 class="font-display text-xl font-extrabold text-navy">Total Packhouse Inventory</h2><span class="text-sm font-bold text-navy">{{ kpis.total_inventory }} total</span></div><DataTable :columns="inventoryColumns" :rows="inventory"><template #status="{row}"><StatusBadge :status="row.status" /></template></DataTable></div><div class="space-y-6"><div class="card p-5"><h2 class="font-display text-xl font-extrabold text-navy">Live Fleet Status</h2><div v-for="(count,status) in fleet_status" :key="status" class="mt-4"><div class="flex justify-between text-sm font-bold"><span>{{ status }}</span><span>{{ count }}</span></div><div class="mt-2 h-2 rounded bg-slate-100"><div class="h-2 rounded bg-gold" :style="{width: Math.min(100,count*18)+'%'}"></div></div></div></div><div class="rounded-lg bg-navy p-6 text-white"><div class="text-gold">Storage Capacity</div><div class="font-display text-4xl font-extrabold">{{ capacity.used }}%</div><p class="mt-2 text-sm text-blue-100">Utilized. Prioritize dispatch if this approaches threshold.</p></div></div></section></AppShell></template>
<script>import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import KpiCard from '../../Components/KpiCard.vue'; import DataTable from '../../Components/DataTable.vue'; import StatusBadge from '../../Components/StatusBadge.vue'; export default{components:{AppShell,PageHeader,KpiCard,DataTable,StatusBadge},props:{kpis:Object,inventory:Array,fleet_status:Object,capacity:Object,recent_activity:Array},computed:{inventoryColumns(){return[{key:'cement_type',label:'Cement Type'},{key:'palletized_quantity',label:'Palletized'},{key:'sling_quantity',label:'Sling'},{key:'tonner_quantity',label:'Tonner'},{key:'total',label:'Total'},{key:'status',label:'Status'}]}}}</script>